_bitmap_cache = {}


def _unpack_bitmap():
    cached = _bitmap_cache.get(PLACEHOLDER_ID)
    if cached is not None:
        return cached

    packed, width, height = _PLACEHOLDER
    bitmap = displayio.Bitmap(width, height, 2)
    bytes_per_row = (width + 7) // 8
    for y in range(height):
        row_offset = y * bytes_per_row
        for x in range(width):
            byte = packed[row_offset + x // 8]
            bitmap[y * width + x] = (byte >> (7 - (x % 8))) & 1

    _bitmap_cache[PLACEHOLDER_ID] = bitmap
    return bitmap


def lookup(emoji_id, foreground, background):
    """Return a TileGrid colored `foreground` on `background`.

    Every `emoji_id` draws the placeholder glyph. Rendering any other
    glyph now happens on the driver side; see
    tasks/ongoing/0039-remove-built-in-firmware-glyph-table.md.
    """
    bitmap = _unpack_bitmap()

    palette = displayio.Palette(2)
    palette[0] = background
    palette[1] = foreground

    return displayio.TileGrid(bitmap, pixel_shader=palette)
